  points = excluded.points,
  updated_at = now();

insert into public.custom_workouts (short_id, title, description, structure, points)
values ('start_w_s06_amrap8', 'AMRAP: пресс, присед, отжимания', 'Тренировка 6. Тот же круг, что в пятой, но теперь по кругу, пока идёт таймер, в спокойном темпе: столько кругов, сколько получится. Не спринтуй первые две минуты — выбери темп, который сможешь держать всё время.',
  '{"sections":[{"kind":"warmup","blockType":"warmup","format":"circuit","sets":1,"setsField":"sets","title":"Разминка: суставная гимнастика","titleEn":"Warm-up: joint mobility","description":"Обязательно перед каждой тренировкой. Идём сверху вниз: шея, плечи, локти и кисти, корпус, таз, колени, стопы. Спокойный темп, амплитуда растёт постепенно, без рывков. Разминка не входит в тренировку — это подготовка. Резкая боль — не норма: остановись.","descriptionEn":"Mandatory before every session. Top to bottom: neck, shoulders, elbows and wrists, trunk, hips, knees, ankles. Easy pace, the range grows gradually, no jerks. The warm-up is not part of the workout — it is preparation. Sharp pain is not normal: stop.","scalable":false,"blockId":"wu_mobility","items":[{"exerciseId":"neck_circles","unit":"seconds","target":20,"restAfterSec":0,"note":"Полукруги спереди, назад не запрокидываем","noteEn":"Half-circles across the front, no dropping back"},{"exerciseId":"arm_circles","unit":"seconds","target":20,"restAfterSec":0,"note":"Половину вперёд, половину назад","noteEn":"Half forward, half backward"},{"exerciseId":"elbow_wrist_circles","unit":"seconds","target":20,"restAfterSec":0},{"exerciseId":"side_bend","unit":"seconds","target":20,"restAfterSec":0},{"exerciseId":"hip_circles","unit":"seconds","target":20,"restAfterSec":0,"note":"В обе стороны","noteEn":"Both directions"},{"exerciseId":"leg_swing","unit":"reps","target":6,"perSide":true,"restAfterSec":0},{"exerciseId":"knee_circles","unit":"seconds","target":20,"restAfterSec":0,"note":"Круги маленькие, пятки на полу","noteEn":"Small circles, heels down"},{"exerciseId":"ankle_circles","unit":"seconds","target":15,"perSide":true,"restAfterSec":0},{"exerciseId":"squat_to_stand","unit":"reps","target":5,"restAfterSec":0,"note":"Медленно, до комфортной глубины","noteEn":"Slowly, to a comfortable depth"}]},{"kind":"main","blockType":"metcon","format":"amrap","sets":1,"setsField":"none","durationSec":480,"title":"Максимум кругов","titleEn":"As many rounds as possible","description":"Максимум кругов за отведённое время в ровном темпе. Ситапы можно заменить «жуком» (вдвое больше).","descriptionEn":"As many rounds as possible in the time at an even pace. Sit-ups can be swapped for dead bugs (twice the reps).","scalable":true,"blockId":"s06_main","items":[{"exerciseId":"sit_up","unit":"reps","target":10,"restAfterSec":0,"note":"Не тяни себя за шею — поднимайся животом. Если ситапы очень тяжело или есть диастаз — «мёртвый жук», в два раза больше повторений","noteEn":"Do not pull on your neck — lift with the abdominals. If sit-ups are very hard or you have diastasis, do dead bugs instead — twice the reps"},{"exerciseId":"air_squat","unit":"reps","target":10,"restAfterSec":0,"note":"Пятки на полу, колени в стороны, глубина комфортная — не садись ниже, чем держится техника","noteEn":"Heels down, knees out, comfortable depth — no lower than your technique holds"},{"exerciseId":"knee_push_up","unit":"reps","target":10,"restAfterSec":0,"note":"Корпус ровно, живот напряжён, таз не проваливаем, локти не разводим широко. Тяжело — от высокой опоры","noteEn":"Body straight, belly braced, hips do not sag, elbows not flared. Too hard? Push up from a high surface"}]},{"kind":"cooldown","blockType":"cooldown","format":"sets","sets":1,"setsField":"sets","title":"Заминка и растяжка","titleEn":"Cool-down and stretch","description":"Не пропускаем. Дыши медленно, тяни до приятного натяжения, не через боль. Потом потрать 2–3 минуты и отметь в приложении, как было: усилие, что далось легко, что оказалось тяжёлым, было ли что-то, что вызвало дискомфорт. Через несколько недель ты увидишь по этим записям, насколько легче стало тренироваться. А если в какой-то день потренироваться не получилось — не страшно, выйди на прогулку.","descriptionEn":"Do not skip it. Breathe slowly, stretch to a pleasant pull, never into pain. Then take 2–3 minutes and record in the app how it went: the effort, what felt easy, what turned out hard, anything that caused discomfort. In a few weeks these notes will show you how much easier training has become. And on a day you could not train at all — no drama, go for a walk.","scalable":false,"blockId":"cd_stretch","items":[{"exerciseId":"cat_cow","unit":"reps","target":6,"restAfterSec":0},{"exerciseId":"quad_stretch","unit":"seconds","target":30,"perSide":true,"restAfterSec":0},{"exerciseId":"hamstring_stretch","unit":"seconds","target":25,"perSide":true,"restAfterSec":0},{"exerciseId":"hip_flexor_stretch","unit":"seconds","target":20,"perSide":true,"restAfterSec":0},{"exerciseId":"child_pose","unit":"seconds","target":45,"restAfterSec":0}]}]}'::jsonb, 100)
on conflict (short_id) do update set
  title = excluded.title,
  description = excluded.description,
  structure = excluded.structure,
  points = excluded.points,
  updated_at = now();

insert into public.custom_workouts (short_id, title, description, structure, points)
values ('start_w_s07_emom_ladder', 'EMOM: присед, отжимания, выпады, пресс', 'Тренировка 7. Каждую минуту новое упражнение, выполнил — отдыхаешь до конца минуты. Круг из четырёх движений: приседания, отжимания с колен, выпады, ситапы. Во втором круге каждое движение — на пару повторов больше; приложение уже посчитало, сколько.',
  '{"sections":[{"kind":"warmup","blockType":"warmup","format":"circuit","sets":1,"setsField":"sets","title":"Разминка: суставная гимнастика","titleEn":"Warm-up: joint mobility","description":"Обязательно перед каждой тренировкой. Идём сверху вниз: шея, плечи, локти и кисти, корпус, таз, колени, стопы. Спокойный темп, амплитуда растёт постепенно, без рывков. Разминка не входит в тренировку — это подготовка. Резкая боль — не норма: остановись.","descriptionEn":"Mandatory before every session. Top to bottom: neck, shoulders, elbows and wrists, trunk, hips, knees, ankles. Easy pace, the range grows gradually, no jerks. The warm-up is not part of the workout — it is preparation. Sharp pain is not normal: stop.","scalable":false,"blockId":"wu_mobility","items":[{"exerciseId":"neck_circles","unit":"seconds","target":20,"restAfterSec":0,"note":"Полукруги спереди, назад не запрокидываем","noteEn":"Half-circles across the front, no dropping back"},{"exerciseId":"arm_circles","unit":"seconds","target":20,"restAfterSec":0,"note":"Половину вперёд, половину назад","noteEn":"Half forward, half backward"},{"exerciseId":"elbow_wrist_circles","unit":"seconds","target":20,"restAfterSec":0},{"exerciseId":"side_bend","unit":"seconds","target":20,"restAfterSec":0},{"exerciseId":"hip_circles","unit":"seconds","target":20,"restAfterSec":0,"note":"В обе стороны","noteEn":"Both directions"},{"exerciseId":"leg_swing","unit":"reps","target":6,"perSide":true,"restAfterSec":0},{"exerciseId":"knee_circles","unit":"seconds","target":20,"restAfterSec":0,"note":"Круги маленькие, пятки на полу","noteEn":"Small circles, heels down"},{"exerciseId":"ankle_circles","unit":"seconds","target":15,"perSide":true,"restAfterSec":0},{"exerciseId":"squat_to_stand","unit":"reps","target":5,"restAfterSec":0,"note":"Медленно, до комфортной глубины","noteEn":"Slowly, to a comfortable depth"}]},{"kind":"main","blockType":"metcon","format":"emom","sets":8,"setsField":"rounds","title":"EMOM, прибавка во втором круге","titleEn":"EMOM, more in the second loop","description":"Первый круг — четыре минуты по базовому числу, второй — те же движения, на пару повторов больше. Выполнил движение — отдыхаешь до конца минуты.","descriptionEn":"The first loop is four minutes at the base count, the second the same movements with a couple more reps. Do the movement, then rest until the minute is up.","scalable":true,"blockId":"s07_main","items":[{"exerciseId":"air_squat","unit":"reps","target":12,"restAfterSec":0,"note":"Пятки на полу, колени в стороны, глубина комфортная — не садись ниже, чем держится техника","noteEn":"Heels down, knees out, comfortable depth — no lower than your technique holds"},{"exerciseId":"knee_push_up","unit":"reps","target":12,"restAfterSec":0,"note":"Корпус ровно, живот напряжён, таз не проваливаем, локти не разводим широко. Тяжело — от высокой опоры","noteEn":"Body straight, belly braced, hips do not sag, elbows not flared. Too hard? Push up from a high surface"},{"exerciseId":"reverse_lunge","unit":"reps","target":12,"restAfterSec":0,"note":"Считаем в сумме на две ноги. Шаг назад, колено мягко к полу, корпус прямой","noteEn":"Counted as the total for both legs. Step back, knee softly to the floor, trunk upright"},{"exerciseId":"sit_up","unit":"reps","target":12,"restAfterSec":0,"note":"Не тяни себя за шею — поднимайся животом. Ситапы тяжело или есть диастаз — «мёртвый жук», столько же повторений: тренер даёт 12–14 за минуту","noteEn":"Do not pull on your neck — lift with the abdominals. Sit-ups hard or diastasis? Dead bugs, the same count: the coach gives 12–14 in the minute"},{"exerciseId":"air_squat","unit":"reps","target":14,"restAfterSec":0,"note":"Пятки на полу, колени в стороны, глубина комфортная — не садись ниже, чем держится техника","noteEn":"Heels down, knees out, comfortable depth — no lower than your technique holds"},{"exerciseId":"knee_push_up","unit":"reps","target":14,"restAfterSec":0,"note":"Корпус ровно, живот напряжён, таз не проваливаем, локти не разводим широко. Тяжело — от высокой опоры","noteEn":"Body straight, belly braced, hips do not sag, elbows not flared. Too hard? Push up from a high surface"},{"exerciseId":"reverse_lunge","unit":"reps","target":14,"restAfterSec":0,"note":"Считаем в сумме на две ноги. Шаг назад, колено мягко к полу, корпус прямой","noteEn":"Counted as the total for both legs. Step back, knee softly to the floor, trunk upright"},{"exerciseId":"sit_up","unit":"reps","target":14,"restAfterSec":0,"note":"Не тяни себя за шею — поднимайся животом. Ситапы тяжело или есть диастаз — «мёртвый жук», столько же повторений: тренер даёт 12–14 за минуту","noteEn":"Do not pull on your neck — lift with the abdominals. Sit-ups hard or diastasis? Dead bugs, the same count: the coach gives 12–14 in the minute"}]},{"kind":"cooldown","blockType":"cooldown","format":"sets","sets":1,"setsField":"sets","title":"Заминка и растяжка","titleEn":"Cool-down and stretch","description":"Не пропускаем. Дыши медленно, тяни до приятного натяжения, не через боль. Потом потрать 2–3 минуты и отметь в приложении, как было: усилие, что далось легко, что оказалось тяжёлым, было ли что-то, что вызвало дискомфорт. Через несколько недель ты увидишь по этим записям, насколько легче стало тренироваться. А если в какой-то день потренироваться не получилось — не страшно, выйди на прогулку.","descriptionEn":"Do not skip it. Breathe slowly, stretch to a pleasant pull, never into pain. Then take 2–3 minutes and record in the app how it went: the effort, what felt easy, what turned out hard, anything that caused discomfort. In a few weeks these notes will show you how much easier training has become. And on a day you could not train at all — no drama, go for a walk.","scalable":false,"blockId":"cd_stretch","items":[{"exerciseId":"cat_cow","unit":"reps","target":6,"restAfterSec":0},{"exerciseId":"quad_stretch","unit":"seconds","target":30,"perSide":true,"restAfterSec":0},{"exerciseId":"hamstring_stretch","unit":"seconds","target":25,"perSide":true,"restAfterSec":0},{"exerciseId":"hip_flexor_stretch","unit":"seconds","target":20,"perSide":true,"restAfterSec":0},{"exerciseId":"child_pose","unit":"seconds","target":45,"restAfterSec":0}]}]}'::jsonb, 100)
on conflict (short_id) do update set
  title = excluded.title,
  description = excluded.description,
  structure = excluded.structure,
  points = excluded.points,
  updated_at = now();

insert into public.custom_workouts (short_id, title, description, structure, points)
values ('start_w_s08_two_rounds', 'Два круга: верх, ноги, кор', 'Тренировка 8. Круг из четырёх движений, в каждом одинаковое число повторений: обратные отжимания, приседания, скалолазы, выпады назад. Два круга на время с крышкой, отдыхаешь когда хочешь. Держи ровный темп и не жертвуй техникой ради секунд.',
  '{"sections":[{"kind":"warmup","blockType":"warmup","format":"circuit","sets":1,"setsField":"sets","title":"Разминка: суставная гимнастика","titleEn":"Warm-up: joint mobility","description":"Обязательно перед каждой тренировкой. Идём сверху вниз: шея, плечи, локти и кисти, корпус, таз, колени, стопы. Спокойный темп, амплитуда растёт постепенно, без рывков. Разминка не входит в тренировку — это подготовка. Резкая боль — не норма: остановись.","descriptionEn":"Mandatory before every session. Top to bottom: neck, shoulders, elbows and wrists, trunk, hips, knees, ankles. Easy pace, the range grows gradually, no jerks. The warm-up is not part of the workout — it is preparation. Sharp pain is not normal: stop.","scalable":false,"blockId":"wu_mobility","items":[{"exerciseId":"neck_circles","unit":"seconds","target":20,"restAfterSec":0,"note":"Полукруги спереди, назад не запрокидываем","noteEn":"Half-circles across the front, no dropping back"},{"exerciseId":"arm_circles","unit":"seconds","target":20,"restAfterSec":0,"note":"Половину вперёд, половину назад","noteEn":"Half forward, half backward"},{"exerciseId":"elbow_wrist_circles","unit":"seconds","target":20,"restAfterSec":0},{"exerciseId":"side_bend","unit":"seconds","target":20,"restAfterSec":0},{"exerciseId":"hip_circles","unit":"seconds","target":20,"restAfterSec":0,"note":"В обе стороны","noteEn":"Both directions"},{"exerciseId":"leg_swing","unit":"reps","target":6,"perSide":true,"restAfterSec":0},{"exerciseId":"knee_circles","unit":"seconds","target":20,"restAfterSec":0,"note":"Круги маленькие, пятки на полу","noteEn":"Small circles, heels down"},{"exerciseId":"ankle_circles","unit":"seconds","target":15,"perSide":true,"restAfterSec":0},{"exerciseId":"squat_to_stand","unit":"reps","target":5,"restAfterSec":0,"note":"Медленно, до комфортной глубины","noteEn":"Slowly, to a comfortable depth"}]},{"kind":"main","blockType":"metcon","format":"fortime","sets":2,"setsField":"sets","durationSec":600,"title":"2 круга на время","titleEn":"2 rounds for time","description":"Крышка — на таймере. Скалолазы считаем по коленям. Отдыхаешь когда хочешь — задача закрыть два круга.","descriptionEn":"The cap is on the timer. Count mountain climbers per knee. Rest whenever — the task is to close two rounds.","scalable":true,"blockId":"s08_main","items":[{"exerciseId":"chair_dip","unit":"reps","target":20,"restAfterSec":0,"note":"Стул без колёсиков, к стене. Локти назад, плечи вниз, опускайся до комфортной глубины","noteEn":"A chair without wheels, against the wall. Elbows back, shoulders down, lower to a comfortable depth"},{"exerciseId":"air_squat","unit":"reps","target":20,"restAfterSec":0,"note":"Пятки на полу, колени в стороны, глубина комфортная — не садись ниже, чем держится техника","noteEn":"Heels down, knees out, comfortable depth — no lower than your technique holds"},{"exerciseId":"mountain_climber","unit":"reps","target":20,"restAfterSec":0,"note":"Плечи над кистями, таз не задираем. Считаем по коленям — каждое колено это повтор","noteEn":"Shoulders over the wrists, hips not piked. Count per knee — every knee drive is a rep"},{"exerciseId":"reverse_lunge","unit":"reps","target":20,"restAfterSec":0,"note":"Считаем в сумме на две ноги. Шаг назад, колено мягко к полу, корпус прямой","noteEn":"Counted as the total for both legs. Step back, knee softly to the floor, trunk upright"}]},{"kind":"cooldown","blockType":"cooldown","format":"sets","sets":1,"setsField":"sets","title":"Заминка и растяжка","titleEn":"Cool-down and stretch","description":"Не пропускаем. Дыши медленно, тяни до приятного натяжения, не через боль. Потом потрать 2–3 минуты и отметь в приложении, как было: усилие, что далось легко, что оказалось тяжёлым, было ли что-то, что вызвало дискомфорт. Через несколько недель ты увидишь по этим записям, насколько легче стало тренироваться. А если в какой-то день потренироваться не получилось — не страшно, выйди на прогулку.","descriptionEn":"Do not skip it. Breathe slowly, stretch to a pleasant pull, never into pain. Then take 2–3 minutes and record in the app how it went: the effort, what felt easy, what turned out hard, anything that caused discomfort. In a few weeks these notes will show you how much easier training has become. And on a day you could not train at all — no drama, go for a walk.","scalable":false,"blockId":"cd_stretch","items":[{"exerciseId":"cat_cow","unit":"reps","target":6,"restAfterSec":0},{"exerciseId":"quad_stretch","unit":"seconds","target":30,"perSide":true,"restAfterSec":0},{"exerciseId":"hamstring_stretch","unit":"seconds","target":25,"perSide":true,"restAfterSec":0},{"exerciseId":"hip_flexor_stretch","unit":"seconds","target":20,"perSide":true,"restAfterSec":0},{"exerciseId":"child_pose","unit":"seconds","target":45,"restAfterSec":0}]}]}'::jsonb, 110)
on conflict (short_id) do update set
  title = excluded.title,
  description = excluded.description,
  structure = excluded.structure,
  points = excluded.points,
  updated_at = now();

insert into public.custom_workouts (short_id, title, description, structure, points)
values ('start_w_s09_for_time', 'Пресс и скалолазы на время', 'Тренировка 9. Два круга на время: ситапы, скалолазы, «жуки» и снова ситапы — скалолазов и «жуков» вдвое больше, чем ситапов. Работа на время — чем быстрее сделаешь, тем быстрее освободишься; отдыхаешь когда хочешь, задача закрыть два круга как можно скорее. Крышка — на таймере.',
  '{"sections":[{"kind":"warmup","blockType":"warmup","format":"circuit","sets":1,"setsField":"sets","title":"Разминка: суставная гимнастика","titleEn":"Warm-up: joint mobility","description":"Обязательно перед каждой тренировкой. Идём сверху вниз: шея, плечи, локти и кисти, корпус, таз, колени, стопы. Спокойный темп, амплитуда растёт постепенно, без рывков. Разминка не входит в тренировку — это подготовка. Резкая боль — не норма: остановись.","descriptionEn":"Mandatory before every session. Top to bottom: neck, shoulders, elbows and wrists, trunk, hips, knees, ankles. Easy pace, the range grows gradually, no jerks. The warm-up is not part of the workout — it is preparation. Sharp pain is not normal: stop.","scalable":false,"blockId":"wu_mobility","items":[{"exerciseId":"neck_circles","unit":"seconds","target":20,"restAfterSec":0,"note":"Полукруги спереди, назад не запрокидываем","noteEn":"Half-circles across the front, no dropping back"},{"exerciseId":"arm_circles","unit":"seconds","target":20,"restAfterSec":0,"note":"Половину вперёд, половину назад","noteEn":"Half forward, half backward"},{"exerciseId":"elbow_wrist_circles","unit":"seconds","target":20,"restAfterSec":0},{"exerciseId":"side_bend","unit":"seconds","target":20,"restAfterSec":0},{"exerciseId":"hip_circles","unit":"seconds","target":20,"restAfterSec":0,"note":"В обе стороны","noteEn":"Both directions"},{"exerciseId":"leg_swing","unit":"reps","target":6,"perSide":true,"restAfterSec":0},{"exerciseId":"knee_circles","unit":"seconds","target":20,"restAfterSec":0,"note":"Круги маленькие, пятки на полу","noteEn":"Small circles, heels down"},{"exerciseId":"ankle_circles","unit":"seconds","target":15,"perSide":true,"restAfterSec":0},{"exerciseId":"squat_to_stand","unit":"reps","target":5,"restAfterSec":0,"note":"Медленно, до комфортной глубины","noteEn":"Slowly, to a comfortable depth"}]},{"kind":"main","blockType":"metcon","format":"fortime","sets":2,"setsField":"sets","durationSec":480,"title":"2 круга на время","titleEn":"2 rounds for time","description":"Крышка — на таймере. Скалолазы по коленям, «жук» медленно и под контролем. Ситапы при диастазе — «жук», вдвое больше.","descriptionEn":"The cap is on the timer. Climbers per knee, dead bugs slow and controlled. Sit-ups with diastasis: dead bugs, twice the reps.","scalable":true,"blockId":"s09_main","items":[{"exerciseId":"sit_up","unit":"reps","target":15,"restAfterSec":0,"note":"Не тяни себя за шею — поднимайся животом. Если ситапы очень тяжело или есть диастаз — «мёртвый жук», в два раза больше повторений","noteEn":"Do not pull on your neck — lift with the abdominals. If sit-ups are very hard or you have diastasis, do dead bugs instead — twice the reps"},{"exerciseId":"mountain_climber","unit":"reps","target":30,"restAfterSec":0,"note":"Плечи над кистями, таз не задираем. Считаем по коленям — каждое колено это повтор","noteEn":"Shoulders over the wrists, hips not piked. Count per knee — every knee drive is a rep"},{"exerciseId":"dead_bug","unit":"reps","target":30,"restAfterSec":0,"note":"Поясница прижата к полу, движения медленные, корпус под контролем","noteEn":"Lower back pressed into the floor, slow movements, trunk under control"},{"exerciseId":"sit_up","unit":"reps","target":15,"restAfterSec":0,"note":"Не тяни себя за шею — поднимайся животом. Если ситапы очень тяжело или есть диастаз — «мёртвый жук», в два раза больше повторений","noteEn":"Do not pull on your neck — lift with the abdominals. If sit-ups are very hard or you have diastasis, do dead bugs instead — twice the reps"}]},{"kind":"cooldown","blockType":"cooldown","format":"sets","sets":1,"setsField":"sets","title":"Заминка и растяжка","titleEn":"Cool-down and stretch","description":"Не пропускаем. Дыши медленно, тяни до приятного натяжения, не через боль. Потом потрать 2–3 минуты и отметь в приложении, как было: усилие, что далось легко, что оказалось тяжёлым, было ли что-то, что вызвало дискомфорт. Через несколько недель ты увидишь по этим записям, насколько легче стало тренироваться. А если в какой-то день потренироваться не получилось — не страшно, выйди на прогулку.","descriptionEn":"Do not skip it. Breathe slowly, stretch to a pleasant pull, never into pain. Then take 2–3 minutes and record in the app how it went: the effort, what felt easy, what turned out hard, anything that caused discomfort. In a few weeks these notes will show you how much easier training has become. And on a day you could not train at all — no drama, go for a walk.","scalable":false,"blockId":"cd_stretch","items":[{"exerciseId":"cat_cow","unit":"reps","target":6,"restAfterSec":0},{"exerciseId":"quad_stretch","unit":"seconds","target":30,"perSide":true,"restAfterSec":0},{"exerciseId":"hamstring_stretch","unit":"seconds","target":25,"perSide":true,"restAfterSec":0},{"exerciseId":"hip_flexor_stretch","unit":"seconds","target":20,"perSide":true,"restAfterSec":0},{"exerciseId":"child_pose","unit":"seconds","target":45,"restAfterSec":0}]}]}'::jsonb, 100)
on conflict (short_id) do update set
  title = excluded.title,
  description = excluded.description,
  structure = excluded.structure,
  points = excluded.points,
  updated_at = now();

insert into public.custom_workouts (short_id, title, description, structure, points)
values ('start_w_s10_every_2min', 'Червячки и приседания', 'Тренировка 10. Короткий круг — червячки и вдвое больше приседаний. Старт раз в 2 минуты: выполнил круг — до конца двухминутки отдыхаешь, приложение отсчитывает отдых само. Червячки — в спокойном темпе, шаг руками не слишком широкий.',
  '{"sections":[{"kind":"warmup","blockType":"warmup","format":"circuit","sets":1,"setsField":"sets","title":"Разминка: суставная гимнастика","titleEn":"Warm-up: joint mobility","description":"Обязательно перед каждой тренировкой. Идём сверху вниз: шея, плечи, локти и кисти, корпус, таз, колени, стопы. Спокойный темп, амплитуда растёт постепенно, без рывков. Разминка не входит в тренировку — это подготовка. Резкая боль — не норма: остановись.","descriptionEn":"Mandatory before every session. Top to bottom: neck, shoulders, elbows and wrists, trunk, hips, knees, ankles. Easy pace, the range grows gradually, no jerks. The warm-up is not part of the workout — it is preparation. Sharp pain is not normal: stop.","scalable":false,"blockId":"wu_mobility","items":[{"exerciseId":"neck_circles","unit":"seconds","target":20,"restAfterSec":0,"note":"Полукруги спереди, назад не запрокидываем","noteEn":"Half-circles across the front, no dropping back"},{"exerciseId":"arm_circles","unit":"seconds","target":20,"restAfterSec":0,"note":"Половину вперёд, половину назад","noteEn":"Half forward, half backward"},{"exerciseId":"elbow_wrist_circles","unit":"seconds","target":20,"restAfterSec":0},{"exerciseId":"side_bend","unit":"seconds","target":20,"restAfterSec":0},{"exerciseId":"hip_circles","unit":"seconds","target":20,"restAfterSec":0,"note":"В обе стороны","noteEn":"Both directions"},{"exerciseId":"leg_swing","unit":"reps","target":6,"perSide":true,"restAfterSec":0},{"exerciseId":"knee_circles","unit":"seconds","target":20,"restAfterSec":0,"note":"Круги маленькие, пятки на полу","noteEn":"Small circles, heels down"},{"exerciseId":"ankle_circles","unit":"seconds","target":15,"perSide":true,"restAfterSec":0},{"exerciseId":"squat_to_stand","unit":"reps","target":5,"restAfterSec":0,"note":"Медленно, до комфортной глубины","noteEn":"Slowly, to a comfortable depth"}]},{"kind":"main","blockType":"metcon","format":"circuit","sets":4,"setsField":"sets","restBetweenRoundsSec":70,"title":"Старт раз в 2 минуты","titleEn":"Start every 2 minutes","description":"Круг без пауз, потом отдых до конца двухминутки — таймер ведёт его сам. Не торопись на червячках.","descriptionEn":"No pauses inside the round, then rest until the 2-minute mark — the timer runs it. Do not rush the inchworms.","scalable":true,"blockId":"s10_main","items":[{"exerciseId":"inchworm","unit":"reps","target":5,"restAfterSec":0,"note":"Шагай руками спокойно, спина ровная, колени можно чуть согнуть","noteEn":"Walk the hands calmly, back flat, knees may bend a little"},{"exerciseId":"air_squat","unit":"reps","target":10,"restAfterSec":0,"note":"Пятки на полу, колени в стороны, глубина комфортная — не садись ниже, чем держится техника","noteEn":"Heels down, knees out, comfortable depth — no lower than your technique holds"}]},{"kind":"cooldown","blockType":"cooldown","format":"sets","sets":1,"setsField":"sets","title":"Заминка и растяжка","titleEn":"Cool-down and stretch","description":"Не пропускаем. Дыши медленно, тяни до приятного натяжения, не через боль. Потом потрать 2–3 минуты и отметь в приложении, как было: усилие, что далось легко, что оказалось тяжёлым, было ли что-то, что вызвало дискомфорт. Через несколько недель ты увидишь по этим записям, насколько легче стало тренироваться. А если в какой-то день потренироваться не получилось — не страшно, выйди на прогулку.","descriptionEn":"Do not skip it. Breathe slowly, stretch to a pleasant pull, never into pain. Then take 2–3 minutes and record in the app how it went: the effort, what felt easy, what turned out hard, anything that caused discomfort. In a few weeks these notes will show you how much easier training has become. And on a day you could not train at all — no drama, go for a walk.","scalable":false,"blockId":"cd_stretch","items":[{"exerciseId":"cat_cow","unit":"reps","target":6,"restAfterSec":0},{"exerciseId":"quad_stretch","unit":"seconds","target":30,"perSide":true,"restAfterSec":0},{"exerciseId":"hamstring_stretch","unit":"seconds","target":25,"perSide":true,"restAfterSec":0},{"exerciseId":"hip_flexor_stretch","unit":"seconds","target":20,"perSide":true,"restAfterSec":0},{"exerciseId":"child_pose","unit":"seconds","target":45,"restAfterSec":0}]}]}'::jsonb, 100)
on conflict (short_id) do update set
  title = excluded.title,
  description = excluded.description,
  structure = excluded.structure,
  points = excluded.points,
  updated_at = now();

insert into public.custom_workouts (short_id, title, description, structure, points)
values ('start_w_s11_emom8', 'EMOM: отжимания, присед, пресс, выпады', 'Тренировка 11. Каждую минуту новое упражнение, выполнил — отдыхаешь до конца минуты. Круг из четырёх движений, у всех одинаковое число повторений: отжимания с колен, приседания, ситапы (или вдвое больше «жуков»), выпады. Два круга.',
  '{"sections":[{"kind":"warmup","blockType":"warmup","format":"circuit","sets":1,"setsField":"sets","title":"Разминка: суставная гимнастика","titleEn":"Warm-up: joint mobility","description":"Обязательно перед каждой тренировкой. Идём сверху вниз: шея, плечи, локти и кисти, корпус, таз, колени, стопы. Спокойный темп, амплитуда растёт постепенно, без рывков. Разминка не входит в тренировку — это подготовка. Резкая боль — не норма: остановись.","descriptionEn":"Mandatory before every session. Top to bottom: neck, shoulders, elbows and wrists, trunk, hips, knees, ankles. Easy pace, the range grows gradually, no jerks. The warm-up is not part of the workout — it is preparation. Sharp pain is not normal: stop.","scalable":false,"blockId":"wu_mobility","items":[{"exerciseId":"neck_circles","unit":"seconds","target":20,"restAfterSec":0,"note":"Полукруги спереди, назад не запрокидываем","noteEn":"Half-circles across the front, no dropping back"},{"exerciseId":"arm_circles","unit":"seconds","target":20,"restAfterSec":0,"note":"Половину вперёд, половину назад","noteEn":"Half forward, half backward"},{"exerciseId":"elbow_wrist_circles","unit":"seconds","target":20,"restAfterSec":0},{"exerciseId":"side_bend","unit":"seconds","target":20,"restAfterSec":0},{"exerciseId":"hip_circles","unit":"seconds","target":20,"restAfterSec":0,"note":"В обе стороны","noteEn":"Both directions"},{"exerciseId":"leg_swing","unit":"reps","target":6,"perSide":true,"restAfterSec":0},{"exerciseId":"knee_circles","unit":"seconds","target":20,"restAfterSec":0,"note":"Круги маленькие, пятки на полу","noteEn":"Small circles, heels down"},{"exerciseId":"ankle_circles","unit":"seconds","target":15,"perSide":true,"restAfterSec":0},{"exerciseId":"squat_to_stand","unit":"reps","target":5,"restAfterSec":0,"note":"Медленно, до комфортной глубины","noteEn":"Slowly, to a comfortable depth"}]},{"kind":"main","blockType":"metcon","format":"emom","sets":8,"setsField":"rounds","title":"Каждую минуту — новое движение","titleEn":"A new movement every minute","description":"Минута 1 — отжимания, 2 — приседания, 3 — ситапы или «жук», 4 — выпады, и снова по кругу.","descriptionEn":"Minute 1 push-ups, 2 squats, 3 sit-ups or dead bugs, 4 lunges, then round again.","scalable":true,"blockId":"s11_main","items":[{"exerciseId":"knee_push_up","unit":"reps","target":10,"restAfterSec":0,"note":"Корпус ровно, живот напряжён, таз не проваливаем, локти не разводим широко. Тяжело — от высокой опоры","noteEn":"Body straight, belly braced, hips do not sag, elbows not flared. Too hard? Push up from a high surface"},{"exerciseId":"air_squat","unit":"reps","target":10,"restAfterSec":0,"note":"Пятки на полу, колени в стороны, глубина комфортная — не садись ниже, чем держится техника","noteEn":"Heels down, knees out, comfortable depth — no lower than your technique holds"},{"exerciseId":"sit_up","unit":"reps","target":10,"restAfterSec":0,"note":"Не тяни себя за шею — поднимайся животом. Если ситапы очень тяжело или есть диастаз — «мёртвый жук», в два раза больше повторений","noteEn":"Do not pull on your neck — lift with the abdominals. If sit-ups are very hard or you have diastasis, do dead bugs instead — twice the reps"},{"exerciseId":"reverse_lunge","unit":"reps","target":10,"restAfterSec":0,"note":"Считаем в сумме на две ноги. Шаг назад, колено мягко к полу, корпус прямой","noteEn":"Counted as the total for both legs. Step back, knee softly to the floor, trunk upright"}]},{"kind":"cooldown","blockType":"cooldown","format":"sets","sets":1,"setsField":"sets","title":"Заминка и растяжка","titleEn":"Cool-down and stretch","description":"Не пропускаем. Дыши медленно, тяни до приятного натяжения, не через боль. Потом потрать 2–3 минуты и отметь в приложении, как было: усилие, что далось легко, что оказалось тяжёлым, было ли что-то, что вызвало дискомфорт. Через несколько недель ты увидишь по этим записям, насколько легче стало тренироваться. А если в какой-то день потренироваться не получилось — не страшно, выйди на прогулку.","descriptionEn":"Do not skip it. Breathe slowly, stretch to a pleasant pull, never into pain. Then take 2–3 minutes and record in the app how it went: the effort, what felt easy, what turned out hard, anything that caused discomfort. In a few weeks these notes will show you how much easier training has become. And on a day you could not train at all — no drama, go for a walk.","scalable":false,"blockId":"cd_stretch","items":[{"exerciseId":"cat_cow","unit":"reps","target":6,"restAfterSec":0},{"exerciseId":"quad_stretch","unit":"seconds","target":30,"perSide":true,"restAfterSec":0},{"exerciseId":"hamstring_stretch","unit":"seconds","target":25,"perSide":true,"restAfterSec":0},{"exerciseId":"hip_flexor_stretch","unit":"seconds","target":20,"perSide":true,"restAfterSec":0},{"exerciseId":"child_pose","unit":"seconds","target":45,"restAfterSec":0}]}]}'::jsonb, 100)
on conflict (short_id) do update set
  title = excluded.title,
