insert into public.custom_workouts (short_id, title, description, structure, points)
values ('start_w_s12_step_ladder', 'Лесенка вниз: зашагивания и червячки', 'Тренировка 12. Лесенка вниз: 10 зашагиваний на каждую ногу и 5 червячков, потом 8 и 4, 6 и 3, 4 и 2, 2 и 1. Работа на время, но на зашагиваниях не торопись — лучше аккуратно и правильно, чем быстро и непонятно как.',
  '{"sections":[{"kind":"warmup","blockType":"warmup","format":"circuit","sets":1,"setsField":"sets","title":"Разминка: суставная гимнастика","titleEn":"Warm-up: joint mobility","description":"Обязательно перед каждой тренировкой. Идём сверху вниз: шея, плечи, локти и кисти, корпус, таз, колени, стопы. Спокойный темп, амплитуда растёт постепенно, без рывков. Разминка не входит в тренировку — это подготовка. Резкая боль — не норма: остановись.","descriptionEn":"Mandatory before every session. Top to bottom: neck, shoulders, elbows and wrists, trunk, hips, knees, ankles. Easy pace, the range grows gradually, no jerks. The warm-up is not part of the workout — it is preparation. Sharp pain is not normal: stop.","scalable":false,"blockId":"wu_mobility","items":[{"exerciseId":"neck_circles","unit":"seconds","target":20,"restAfterSec":0,"note":"Полукруги спереди, назад не запрокидываем","noteEn":"Half-circles across the front, no dropping back"},{"exerciseId":"arm_circles","unit":"seconds","target":20,"restAfterSec":0,"note":"Половину вперёд, половину назад","noteEn":"Half forward, half backward"},{"exerciseId":"elbow_wrist_circles","unit":"seconds","target":20,"restAfterSec":0},{"exerciseId":"side_bend","unit":"seconds","target":20,"restAfterSec":0},{"exerciseId":"hip_circles","unit":"seconds","target":20,"restAfterSec":0,"note":"В обе стороны","noteEn":"Both directions"},{"exerciseId":"leg_swing","unit":"reps","target":6,"perSide":true,"restAfterSec":0},{"exerciseId":"knee_circles","unit":"seconds","target":20,"restAfterSec":0,"note":"Круги маленькие, пятки на полу","noteEn":"Small circles, heels down"},{"exerciseId":"ankle_circles","unit":"seconds","target":15,"perSide":true,"restAfterSec":0},{"exerciseId":"squat_to_stand","unit":"reps","target":5,"restAfterSec":0,"note":"Медленно, до комфортной глубины","noteEn":"Slowly, to a comfortable depth"}]},{"kind":"main","blockType":"metcon","format":"fortime","sets":1,"setsField":"sets","durationSec":600,"title":"Лесенка на время","titleEn":"The ladder for time","description":"Крышка 10 минут. Зашагивания — на стул без колёсиков или на ступеньку; вставай через пятку и полностью выпрямляйся наверху.","descriptionEn":"10-minute cap. Step-ups onto a chair without wheels or a stair step; drive through the heel and stand up fully at the top.","scalable":false,"blockId":"s12_main","items":[{"exerciseId":"step_up","unit":"reps","target":10,"perSide":true,"restAfterSec":0,"note":"Вставай через пятку, наверху выпрямись полностью, спускайся под контролем","noteEn":"Drive through the heel, stand up fully at the top, step down under control"},{"exerciseId":"inchworm","unit":"reps","target":5,"restAfterSec":0,"note":"Шагай руками спокойно, спина ровная, колени можно чуть согнуть","noteEn":"Walk the hands calmly, back flat, knees may bend a little"},{"exerciseId":"step_up","unit":"reps","target":8,"perSide":true,"restAfterSec":0,"note":"Вставай через пятку, наверху выпрямись полностью, спускайся под контролем","noteEn":"Drive through the heel, stand up fully at the top, step down under control"},{"exerciseId":"inchworm","unit":"reps","target":4,"restAfterSec":0,"note":"Шагай руками спокойно, спина ровная, колени можно чуть согнуть","noteEn":"Walk the hands calmly, back flat, knees may bend a little"},{"exerciseId":"step_up","unit":"reps","target":6,"perSide":true,"restAfterSec":0,"note":"Вставай через пятку, наверху выпрямись полностью, спускайся под контролем","noteEn":"Drive through the heel, stand up fully at the top, step down under control"},{"exerciseId":"inchworm","unit":"reps","target":3,"restAfterSec":0,"note":"Шагай руками спокойно, спина ровная, колени можно чуть согнуть","noteEn":"Walk the hands calmly, back flat, knees may bend a little"},{"exerciseId":"step_up","unit":"reps","target":4,"perSide":true,"restAfterSec":0,"note":"Вставай через пятку, наверху выпрямись полностью, спускайся под контролем","noteEn":"Drive through the heel, stand up fully at the top, step down under control"},{"exerciseId":"inchworm","unit":"reps","target":2,"restAfterSec":0,"note":"Шагай руками спокойно, спина ровная, колени можно чуть согнуть","noteEn":"Walk the hands calmly, back flat, knees may bend a little"},{"exerciseId":"step_up","unit":"reps","target":2,"perSide":true,"restAfterSec":0,"note":"Вставай через пятку, наверху выпрямись полностью, спускайся под контролем","noteEn":"Drive through the heel, stand up fully at the top, step down under control"},{"exerciseId":"inchworm","unit":"reps","target":1,"restAfterSec":0,"note":"Шагай руками спокойно, спина ровная, колени можно чуть согнуть","noteEn":"Walk the hands calmly, back flat, knees may bend a little"}]},{"kind":"cooldown","blockType":"cooldown","format":"sets","sets":1,"setsField":"sets","title":"Заминка и растяжка","titleEn":"Cool-down and stretch","description":"Не пропускаем. Дыши медленно, тяни до приятного натяжения, не через боль. Потом потрать 2–3 минуты и отметь в приложении, как было: усилие, что далось легко, что оказалось тяжёлым, было ли что-то, что вызвало дискомфорт. Через несколько недель ты увидишь по этим записям, насколько легче стало тренироваться. А если в какой-то день потренироваться не получилось — не страшно, выйди на прогулку.","descriptionEn":"Do not skip it. Breathe slowly, stretch to a pleasant pull, never into pain. Then take 2–3 minutes and record in the app how it went: the effort, what felt easy, what turned out hard, anything that caused discomfort. In a few weeks these notes will show you how much easier training has become. And on a day you could not train at all — no drama, go for a walk.","scalable":false,"blockId":"cd_stretch","items":[{"exerciseId":"cat_cow","unit":"reps","target":6,"restAfterSec":0},{"exerciseId":"quad_stretch","unit":"seconds","target":30,"perSide":true,"restAfterSec":0},{"exerciseId":"hamstring_stretch","unit":"seconds","target":25,"perSide":true,"restAfterSec":0},{"exerciseId":"hip_flexor_stretch","unit":"seconds","target":20,"perSide":true,"restAfterSec":0},{"exerciseId":"child_pose","unit":"seconds","target":45,"restAfterSec":0}]}]}'::jsonb, 100)
on conflict (short_id) do update set
  title = excluded.title,
