insert into public.custom_workouts (short_id, title, description, structure, points)
values ('start_w_s13_ladder5', 'Пять движений, максимум кругов', 'Тренировка 13. Немного усложняем: круг из пяти движений — 5 червячков, 6 ситапов, 7 отжиманий с колен, 8 выпадов, 9 приседаний. За отведённое время — максимум кругов, ориентир три круга. Ровный темп важнее скорости.',
  '{"sections":[{"kind":"warmup","blockType":"warmup","format":"circuit","sets":1,"setsField":"sets","title":"Разминка: суставная гимнастика","titleEn":"Warm-up: joint mobility","description":"Обязательно перед каждой тренировкой. Идём сверху вниз: шея, плечи, локти и кисти, корпус, таз, колени, стопы. Спокойный темп, амплитуда растёт постепенно, без рывков. Разминка не входит в тренировку — это подготовка. Резкая боль — не норма: остановись.","descriptionEn":"Mandatory before every session. Top to bottom: neck, shoulders, elbows and wrists, trunk, hips, knees, ankles. Easy pace, the range grows gradually, no jerks. The warm-up is not part of the workout — it is preparation. Sharp pain is not normal: stop.","scalable":false,"blockId":"wu_mobility","items":[{"exerciseId":"neck_circles","unit":"seconds","target":20,"restAfterSec":0,"note":"Полукруги спереди, назад не запрокидываем","noteEn":"Half-circles across the front, no dropping back"},{"exerciseId":"arm_circles","unit":"seconds","target":20,"restAfterSec":0,"note":"Половину вперёд, половину назад","noteEn":"Half forward, half backward"},{"exerciseId":"elbow_wrist_circles","unit":"seconds","target":20,"restAfterSec":0},{"exerciseId":"side_bend","unit":"seconds","target":20,"restAfterSec":0},{"exerciseId":"hip_circles","unit":"seconds","target":20,"restAfterSec":0,"note":"В обе стороны","noteEn":"Both directions"},{"exerciseId":"leg_swing","unit":"reps","target":6,"perSide":true,"restAfterSec":0},{"exerciseId":"knee_circles","unit":"seconds","target":20,"restAfterSec":0,"note":"Круги маленькие, пятки на полу","noteEn":"Small circles, heels down"},{"exerciseId":"ankle_circles","unit":"seconds","target":15,"perSide":true,"restAfterSec":0},{"exerciseId":"squat_to_stand","unit":"reps","target":5,"restAfterSec":0,"note":"Медленно, до комфортной глубины","noteEn":"Slowly, to a comfortable depth"}]},{"kind":"main","blockType":"metcon","format":"amrap","sets":1,"setsField":"none","durationSec":480,"title":"Максимум кругов","titleEn":"As many rounds as possible","description":"Максимум кругов за 8 минут, ориентир — три круга. Выпады считаем в сумме на две ноги.","descriptionEn":"As many rounds as possible in 8 minutes, three is the mark. Lunges counted as the total for both legs.","scalable":false,"blockId":"s13_main","items":[{"exerciseId":"inchworm","unit":"reps","target":5,"restAfterSec":0,"note":"Шагай руками спокойно, спина ровная, колени можно чуть согнуть","noteEn":"Walk the hands calmly, back flat, knees may bend a little"},{"exerciseId":"sit_up","unit":"reps","target":6,"restAfterSec":0,"note":"Не тяни себя за шею — поднимайся животом. Если ситапы очень тяжело или есть диастаз — «мёртвый жук», в два раза больше повторений","noteEn":"Do not pull on your neck — lift with the abdominals. If sit-ups are very hard or you have diastasis, do dead bugs instead — twice the reps"},{"exerciseId":"knee_push_up","unit":"reps","target":7,"restAfterSec":0,"note":"Корпус ровно, живот напряжён, таз не проваливаем, локти не разводим широко. Тяжело — от высокой опоры","noteEn":"Body straight, belly braced, hips do not sag, elbows not flared. Too hard? Push up from a high surface"},{"exerciseId":"reverse_lunge","unit":"reps","target":8,"restAfterSec":0,"note":"Считаем в сумме на две ноги. Шаг назад, колено мягко к полу, корпус прямой","noteEn":"Counted as the total for both legs. Step back, knee softly to the floor, trunk upright"},{"exerciseId":"air_squat","unit":"reps","target":9,"restAfterSec":0,"note":"Пятки на полу, колени в стороны, глубина комфортная — не садись ниже, чем держится техника","noteEn":"Heels down, knees out, comfortable depth — no lower than your technique holds"}]},{"kind":"cooldown","blockType":"cooldown","format":"sets","sets":1,"setsField":"sets","title":"Заминка и растяжка","titleEn":"Cool-down and stretch","description":"Не пропускаем. Дыши медленно, тяни до приятного натяжения, не через боль. Потом потрать 2–3 минуты и отметь в приложении, как было: усилие, что далось легко, что оказалось тяжёлым, было ли что-то, что вызвало дискомфорт. Через несколько недель ты увидишь по этим записям, насколько легче стало тренироваться. А если в какой-то день потренироваться не получилось — не страшно, выйди на прогулку.","descriptionEn":"Do not skip it. Breathe slowly, stretch to a pleasant pull, never into pain. Then take 2–3 minutes and record in the app how it went: the effort, what felt easy, what turned out hard, anything that caused discomfort. In a few weeks these notes will show you how much easier training has become. And on a day you could not train at all — no drama, go for a walk.","scalable":false,"blockId":"cd_stretch","items":[{"exerciseId":"cat_cow","unit":"reps","target":6,"restAfterSec":0},{"exerciseId":"quad_stretch","unit":"seconds","target":30,"perSide":true,"restAfterSec":0},{"exerciseId":"hamstring_stretch","unit":"seconds","target":25,"perSide":true,"restAfterSec":0},{"exerciseId":"hip_flexor_stretch","unit":"seconds","target":20,"perSide":true,"restAfterSec":0},{"exerciseId":"child_pose","unit":"seconds","target":45,"restAfterSec":0}]}]}'::jsonb, 100)
on conflict (short_id) do update set
  title = excluded.title,
  description = excluded.description,
  structure = excluded.structure,
  points = excluded.points,
  updated_at = now();

insert into public.custom_workouts (short_id, title, description, structure, points)
values ('start_w_s14_double', 'Выпады, отжимания, твисты: два круга', 'Тренировка 14. Два круга. Первый: выпады назад, отжимания с колен, русские твисты (или вдвое больше «жуков»). Отдых 2 минуты. Второй — те же движения, но каждого вдвое больше. Второй круг длинный, разбивай на подходы и держи технику.',
  '{"sections":[{"kind":"warmup","blockType":"warmup","format":"circuit","sets":1,"setsField":"sets","title":"Разминка: суставная гимнастика","titleEn":"Warm-up: joint mobility","description":"Обязательно перед каждой тренировкой. Идём сверху вниз: шея, плечи, локти и кисти, корпус, таз, колени, стопы. Спокойный темп, амплитуда растёт постепенно, без рывков. Разминка не входит в тренировку — это подготовка. Резкая боль — не норма: остановись.","descriptionEn":"Mandatory before every session. Top to bottom: neck, shoulders, elbows and wrists, trunk, hips, knees, ankles. Easy pace, the range grows gradually, no jerks. The warm-up is not part of the workout — it is preparation. Sharp pain is not normal: stop.","scalable":false,"blockId":"wu_mobility","items":[{"exerciseId":"neck_circles","unit":"seconds","target":20,"restAfterSec":0,"note":"Полукруги спереди, назад не запрокидываем","noteEn":"Half-circles across the front, no dropping back"},{"exerciseId":"arm_circles","unit":"seconds","target":20,"restAfterSec":0,"note":"Половину вперёд, половину назад","noteEn":"Half forward, half backward"},{"exerciseId":"elbow_wrist_circles","unit":"seconds","target":20,"restAfterSec":0},{"exerciseId":"side_bend","unit":"seconds","target":20,"restAfterSec":0},{"exerciseId":"hip_circles","unit":"seconds","target":20,"restAfterSec":0,"note":"В обе стороны","noteEn":"Both directions"},{"exerciseId":"leg_swing","unit":"reps","target":6,"perSide":true,"restAfterSec":0},{"exerciseId":"knee_circles","unit":"seconds","target":20,"restAfterSec":0,"note":"Круги маленькие, пятки на полу","noteEn":"Small circles, heels down"},{"exerciseId":"ankle_circles","unit":"seconds","target":15,"perSide":true,"restAfterSec":0},{"exerciseId":"squat_to_stand","unit":"reps","target":5,"restAfterSec":0,"note":"Медленно, до комфортной глубины","noteEn":"Slowly, to a comfortable depth"}]},{"kind":"main","blockType":"metcon","format":"fortime","sets":1,"setsField":"sets","durationSec":360,"title":"Первый круг","titleEn":"The first round","description":"Каждое движение по разу, потом отдых 2 минуты перед вторым кругом.","descriptionEn":"Each movement once, then rest 2 minutes before the second round.","scalable":true,"blockId":"s14_first","items":[{"exerciseId":"reverse_lunge","unit":"reps","target":20,"restAfterSec":0,"note":"Считаем в сумме на две ноги. Шаг назад, колено мягко к полу, корпус прямой","noteEn":"Counted as the total for both legs. Step back, knee softly to the floor, trunk upright"},{"exerciseId":"knee_push_up","unit":"reps","target":20,"restAfterSec":0,"note":"Корпус ровно, живот напряжён, таз не проваливаем, локти не разводим широко. Тяжело — от высокой опоры","noteEn":"Body straight, belly braced, hips do not sag, elbows not flared. Too hard? Push up from a high surface"},{"exerciseId":"russian_twist","unit":"reps","target":20,"restAfterSec":0,"note":"Спина прямая, поворот от корпуса, а не руками. При диастазе — «мёртвый жук», вдвое больше","noteEn":"Back straight, twist from the trunk, not the arms. With diastasis, dead bugs — twice the reps"}]},{"kind":"main","blockType":"metcon","format":"fortime","sets":1,"setsField":"sets","durationSec":600,"title":"Второй круг, вдвое длиннее","titleEn":"The second round, twice as long","description":"После двух минут отдыха — каждого движения вдвое больше. Разбивай на подходы, техника важнее скорости.","descriptionEn":"After two minutes of rest — twice as many of each. Break it into sets, technique over speed.","scalable":true,"blockId":"s14_second","items":[{"exerciseId":"reverse_lunge","unit":"reps","target":40,"restAfterSec":0,"note":"Считаем в сумме на две ноги. Шаг назад, колено мягко к полу, корпус прямой","noteEn":"Counted as the total for both legs. Step back, knee softly to the floor, trunk upright"},{"exerciseId":"knee_push_up","unit":"reps","target":40,"restAfterSec":0,"note":"Корпус ровно, живот напряжён, таз не проваливаем, локти не разводим широко. Тяжело — от высокой опоры","noteEn":"Body straight, belly braced, hips do not sag, elbows not flared. Too hard? Push up from a high surface"},{"exerciseId":"russian_twist","unit":"reps","target":40,"restAfterSec":0,"note":"Спина прямая, поворот от корпуса, а не руками. При диастазе — «мёртвый жук», вдвое больше","noteEn":"Back straight, twist from the trunk, not the arms. With diastasis, dead bugs — twice the reps"}]},{"kind":"cooldown","blockType":"cooldown","format":"sets","sets":1,"setsField":"sets","title":"Заминка и растяжка","titleEn":"Cool-down and stretch","description":"Не пропускаем. Дыши медленно, тяни до приятного натяжения, не через боль. Потом потрать 2–3 минуты и отметь в приложении, как было: усилие, что далось легко, что оказалось тяжёлым, было ли что-то, что вызвало дискомфорт. Через несколько недель ты увидишь по этим записям, насколько легче стало тренироваться. А если в какой-то день потренироваться не получилось — не страшно, выйди на прогулку.","descriptionEn":"Do not skip it. Breathe slowly, stretch to a pleasant pull, never into pain. Then take 2–3 minutes and record in the app how it went: the effort, what felt easy, what turned out hard, anything that caused discomfort. In a few weeks these notes will show you how much easier training has become. And on a day you could not train at all — no drama, go for a walk.","scalable":false,"blockId":"cd_stretch","items":[{"exerciseId":"cat_cow","unit":"reps","target":6,"restAfterSec":0},{"exerciseId":"quad_stretch","unit":"seconds","target":30,"perSide":true,"restAfterSec":0},{"exerciseId":"hamstring_stretch","unit":"seconds","target":25,"perSide":true,"restAfterSec":0},{"exerciseId":"hip_flexor_stretch","unit":"seconds","target":20,"perSide":true,"restAfterSec":0},{"exerciseId":"child_pose","unit":"seconds","target":45,"restAfterSec":0}]}]}'::jsonb, 110)
on conflict (short_id) do update set
  title = excluded.title,
  description = excluded.description,
  structure = excluded.structure,
  points = excluded.points,
  updated_at = now();

insert into public.custom_workouts (short_id, title, description, structure, points)
values ('start_w_s15_amrap8', 'AMRAP: отжимания, присед, скалолазы', 'Тренировка 15. По кругу, пока идёт таймер: отжимания, вдвое больше приседаний и ещё вдвое больше скалолазов. Обычные отжимания — тяжело, делай с колен. Ровный темп: столько кругов, сколько получится держать до конца.',
  '{"sections":[{"kind":"warmup","blockType":"warmup","format":"circuit","sets":1,"setsField":"sets","title":"Разминка: суставная гимнастика","titleEn":"Warm-up: joint mobility","description":"Обязательно перед каждой тренировкой. Идём сверху вниз: шея, плечи, локти и кисти, корпус, таз, колени, стопы. Спокойный темп, амплитуда растёт постепенно, без рывков. Разминка не входит в тренировку — это подготовка. Резкая боль — не норма: остановись.","descriptionEn":"Mandatory before every session. Top to bottom: neck, shoulders, elbows and wrists, trunk, hips, knees, ankles. Easy pace, the range grows gradually, no jerks. The warm-up is not part of the workout — it is preparation. Sharp pain is not normal: stop.","scalable":false,"blockId":"wu_mobility","items":[{"exerciseId":"neck_circles","unit":"seconds","target":20,"restAfterSec":0,"note":"Полукруги спереди, назад не запрокидываем","noteEn":"Half-circles across the front, no dropping back"},{"exerciseId":"arm_circles","unit":"seconds","target":20,"restAfterSec":0,"note":"Половину вперёд, половину назад","noteEn":"Half forward, half backward"},{"exerciseId":"elbow_wrist_circles","unit":"seconds","target":20,"restAfterSec":0},{"exerciseId":"side_bend","unit":"seconds","target":20,"restAfterSec":0},{"exerciseId":"hip_circles","unit":"seconds","target":20,"restAfterSec":0,"note":"В обе стороны","noteEn":"Both directions"},{"exerciseId":"leg_swing","unit":"reps","target":6,"perSide":true,"restAfterSec":0},{"exerciseId":"knee_circles","unit":"seconds","target":20,"restAfterSec":0,"note":"Круги маленькие, пятки на полу","noteEn":"Small circles, heels down"},{"exerciseId":"ankle_circles","unit":"seconds","target":15,"perSide":true,"restAfterSec":0},{"exerciseId":"squat_to_stand","unit":"reps","target":5,"restAfterSec":0,"note":"Медленно, до комфортной глубины","noteEn":"Slowly, to a comfortable depth"}]},{"kind":"main","blockType":"metcon","format":"amrap","sets":1,"setsField":"none","durationSec":480,"title":"Максимум кругов","titleEn":"As many rounds as possible","description":"Максимум кругов за отведённое время. Скалолазы по коленям. Отжимания тяжело — с колен.","descriptionEn":"As many rounds as possible in the time. Climbers per knee. Push-ups hard? From the knees.","scalable":true,"blockId":"s15_main","items":[{"exerciseId":"push_up","unit":"reps","target":8,"restAfterSec":0,"note":"Корпус ровно, локти назад под 45°, грудь к полу. Тяжело — с колен или от высокой опоры","noteEn":"Body straight, elbows back at 45 degrees, chest to the floor. Too hard? From the knees or a high surface"},{"exerciseId":"air_squat","unit":"reps","target":16,"restAfterSec":0,"note":"Пятки на полу, колени в стороны, глубина комфортная — не садись ниже, чем держится техника","noteEn":"Heels down, knees out, comfortable depth — no lower than your technique holds"},{"exerciseId":"mountain_climber","unit":"reps","target":32,"restAfterSec":0,"note":"Плечи над кистями, таз не задираем. Считаем по коленям — каждое колено это повтор","noteEn":"Shoulders over the wrists, hips not piked. Count per knee — every knee drive is a rep"}]},{"kind":"cooldown","blockType":"cooldown","format":"sets","sets":1,"setsField":"sets","title":"Заминка и растяжка","titleEn":"Cool-down and stretch","description":"Не пропускаем. Дыши медленно, тяни до приятного натяжения, не через боль. Потом потрать 2–3 минуты и отметь в приложении, как было: усилие, что далось легко, что оказалось тяжёлым, было ли что-то, что вызвало дискомфорт. Через несколько недель ты увидишь по этим записям, насколько легче стало тренироваться. А если в какой-то день потренироваться не получилось — не страшно, выйди на прогулку.","descriptionEn":"Do not skip it. Breathe slowly, stretch to a pleasant pull, never into pain. Then take 2–3 minutes and record in the app how it went: the effort, what felt easy, what turned out hard, anything that caused discomfort. In a few weeks these notes will show you how much easier training has become. And on a day you could not train at all — no drama, go for a walk.","scalable":false,"blockId":"cd_stretch","items":[{"exerciseId":"cat_cow","unit":"reps","target":6,"restAfterSec":0},{"exerciseId":"quad_stretch","unit":"seconds","target":30,"perSide":true,"restAfterSec":0},{"exerciseId":"hamstring_stretch","unit":"seconds","target":25,"perSide":true,"restAfterSec":0},{"exerciseId":"hip_flexor_stretch","unit":"seconds","target":20,"perSide":true,"restAfterSec":0},{"exerciseId":"child_pose","unit":"seconds","target":45,"restAfterSec":0}]}]}'::jsonb, 100)
on conflict (short_id) do update set
  title = excluded.title,
  description = excluded.description,
  structure = excluded.structure,
  points = excluded.points,
  updated_at = now();

insert into public.custom_workouts (short_id, title, description, structure, points)
values ('start_w_s16_chipper', 'Чиппер: присед, выпады, зашагивания, червячки', 'Тренировка 16. Длинный список на время: приседания, выпады, зашагивания, червячки — от самого большого числа к самому маленькому. Порядок менять нельзя — идём сверху вниз. Крышка — на таймере; разбивай на подходы, но не меняй последовательность.',
  '{"sections":[{"kind":"warmup","blockType":"warmup","format":"circuit","sets":1,"setsField":"sets","title":"Разминка: суставная гимнастика","titleEn":"Warm-up: joint mobility","description":"Обязательно перед каждой тренировкой. Идём сверху вниз: шея, плечи, локти и кисти, корпус, таз, колени, стопы. Спокойный темп, амплитуда растёт постепенно, без рывков. Разминка не входит в тренировку — это подготовка. Резкая боль — не норма: остановись.","descriptionEn":"Mandatory before every session. Top to bottom: neck, shoulders, elbows and wrists, trunk, hips, knees, ankles. Easy pace, the range grows gradually, no jerks. The warm-up is not part of the workout — it is preparation. Sharp pain is not normal: stop.","scalable":false,"blockId":"wu_mobility","items":[{"exerciseId":"neck_circles","unit":"seconds","target":20,"restAfterSec":0,"note":"Полукруги спереди, назад не запрокидываем","noteEn":"Half-circles across the front, no dropping back"},{"exerciseId":"arm_circles","unit":"seconds","target":20,"restAfterSec":0,"note":"Половину вперёд, половину назад","noteEn":"Half forward, half backward"},{"exerciseId":"elbow_wrist_circles","unit":"seconds","target":20,"restAfterSec":0},{"exerciseId":"side_bend","unit":"seconds","target":20,"restAfterSec":0},{"exerciseId":"hip_circles","unit":"seconds","target":20,"restAfterSec":0,"note":"В обе стороны","noteEn":"Both directions"},{"exerciseId":"leg_swing","unit":"reps","target":6,"perSide":true,"restAfterSec":0},{"exerciseId":"knee_circles","unit":"seconds","target":20,"restAfterSec":0,"note":"Круги маленькие, пятки на полу","noteEn":"Small circles, heels down"},{"exerciseId":"ankle_circles","unit":"seconds","target":15,"perSide":true,"restAfterSec":0},{"exerciseId":"squat_to_stand","unit":"reps","target":5,"restAfterSec":0,"note":"Медленно, до комфортной глубины","noteEn":"Slowly, to a comfortable depth"}]},{"kind":"main","blockType":"metcon","format":"fortime","sets":1,"setsField":"sets","durationSec":780,"title":"Чиппер на время","titleEn":"The chipper for time","description":"Крышка — на таймере. Выпады и зашагивания считаем в сумме на две ноги. Порядок менять нельзя.","descriptionEn":"The cap is on the timer. Lunges and step-ups counted as the total for both legs. Do not change the order.","scalable":true,"blockId":"s16_main","items":[{"exerciseId":"air_squat","unit":"reps","target":60,"restAfterSec":0,"note":"Пятки на полу, колени в стороны, глубина комфортная — не садись ниже, чем держится техника","noteEn":"Heels down, knees out, comfortable depth — no lower than your technique holds"},{"exerciseId":"reverse_lunge","unit":"reps","target":40,"restAfterSec":0,"note":"Считаем в сумме на две ноги. Шаг назад, колено мягко к полу, корпус прямой","noteEn":"Counted as the total for both legs. Step back, knee softly to the floor, trunk upright"},{"exerciseId":"step_up","unit":"reps","target":30,"restAfterSec":0,"note":"В сумме на две ноги","noteEn":"Total for both legs"},{"exerciseId":"inchworm","unit":"reps","target":20,"restAfterSec":0,"note":"Шагай руками спокойно, спина ровная, колени можно чуть согнуть","noteEn":"Walk the hands calmly, back flat, knees may bend a little"}]},{"kind":"cooldown","blockType":"cooldown","format":"sets","sets":1,"setsField":"sets","title":"Заминка и растяжка","titleEn":"Cool-down and stretch","description":"Не пропускаем. Дыши медленно, тяни до приятного натяжения, не через боль. Потом потрать 2–3 минуты и отметь в приложении, как было: усилие, что далось легко, что оказалось тяжёлым, было ли что-то, что вызвало дискомфорт. Через несколько недель ты увидишь по этим записям, насколько легче стало тренироваться. А если в какой-то день потренироваться не получилось — не страшно, выйди на прогулку.","descriptionEn":"Do not skip it. Breathe slowly, stretch to a pleasant pull, never into pain. Then take 2–3 minutes and record in the app how it went: the effort, what felt easy, what turned out hard, anything that caused discomfort. In a few weeks these notes will show you how much easier training has become. And on a day you could not train at all — no drama, go for a walk.","scalable":false,"blockId":"cd_stretch","items":[{"exerciseId":"cat_cow","unit":"reps","target":6,"restAfterSec":0},{"exerciseId":"quad_stretch","unit":"seconds","target":30,"perSide":true,"restAfterSec":0},{"exerciseId":"hamstring_stretch","unit":"seconds","target":25,"perSide":true,"restAfterSec":0},{"exerciseId":"hip_flexor_stretch","unit":"seconds","target":20,"perSide":true,"restAfterSec":0},{"exerciseId":"child_pose","unit":"seconds","target":45,"restAfterSec":0}]}]}'::jsonb, 120)
on conflict (short_id) do update set
  title = excluded.title,
  description = excluded.description,
  structure = excluded.structure,
  points = excluded.points,
  updated_at = now();

insert into public.custom_workouts (short_id, title, description, structure, points)
values ('start_w_s17_buyin', 'Входной билет и червячки', 'Тренировка 17. Круг — это входной билет (отжимания, приседания, ситапы поровну), а за ним червячки. После круга — 3 минуты отдыха, и следующий круг. Червячки не торопи: тренер просит, чтобы в каждом круге их выходило одинаково.',
  '{"sections":[{"kind":"warmup","blockType":"warmup","format":"circuit","sets":1,"setsField":"sets","title":"Разминка: суставная гимнастика","titleEn":"Warm-up: joint mobility","description":"Обязательно перед каждой тренировкой. Идём сверху вниз: шея, плечи, локти и кисти, корпус, таз, колени, стопы. Спокойный темп, амплитуда растёт постепенно, без рывков. Разминка не входит в тренировку — это подготовка. Резкая боль — не норма: остановись.","descriptionEn":"Mandatory before every session. Top to bottom: neck, shoulders, elbows and wrists, trunk, hips, knees, ankles. Easy pace, the range grows gradually, no jerks. The warm-up is not part of the workout — it is preparation. Sharp pain is not normal: stop.","scalable":false,"blockId":"wu_mobility","items":[{"exerciseId":"neck_circles","unit":"seconds","target":20,"restAfterSec":0,"note":"Полукруги спереди, назад не запрокидываем","noteEn":"Half-circles across the front, no dropping back"},{"exerciseId":"arm_circles","unit":"seconds","target":20,"restAfterSec":0,"note":"Половину вперёд, половину назад","noteEn":"Half forward, half backward"},{"exerciseId":"elbow_wrist_circles","unit":"seconds","target":20,"restAfterSec":0},{"exerciseId":"side_bend","unit":"seconds","target":20,"restAfterSec":0},{"exerciseId":"hip_circles","unit":"seconds","target":20,"restAfterSec":0,"note":"В обе стороны","noteEn":"Both directions"},{"exerciseId":"leg_swing","unit":"reps","target":6,"perSide":true,"restAfterSec":0},{"exerciseId":"knee_circles","unit":"seconds","target":20,"restAfterSec":0,"note":"Круги маленькие, пятки на полу","noteEn":"Small circles, heels down"},{"exerciseId":"ankle_circles","unit":"seconds","target":15,"perSide":true,"restAfterSec":0},{"exerciseId":"squat_to_stand","unit":"reps","target":5,"restAfterSec":0,"note":"Медленно, до комфортной глубины","noteEn":"Slowly, to a comfortable depth"}]},{"kind":"main","blockType":"metcon","format":"circuit","sets":2,"setsField":"sets","restBetweenRoundsSec":180,"title":"Круги: 3 минуты отдыха после круга","titleEn":"Rounds: 3 minutes of rest after each","description":"Входной билет, потом червячки. После круга — 3 минуты отдыха, таймер ведёт его сам. Отжимания тяжело — с колен.","descriptionEn":"The buy-in, then inchworms. After the round, 3 minutes of rest — the timer runs it. Push-ups hard? From the knees.","scalable":true,"blockId":"s17_main","items":[{"exerciseId":"push_up","unit":"reps","target":10,"restAfterSec":0,"note":"Корпус ровно, локти назад под 45°, грудь к полу. Тяжело — с колен или от высокой опоры","noteEn":"Body straight, elbows back at 45 degrees, chest to the floor. Too hard? From the knees or a high surface"},{"exerciseId":"air_squat","unit":"reps","target":10,"restAfterSec":0,"note":"Пятки на полу, колени в стороны, глубина комфортная — не садись ниже, чем держится техника","noteEn":"Heels down, knees out, comfortable depth — no lower than your technique holds"},{"exerciseId":"sit_up","unit":"reps","target":10,"restAfterSec":0,"note":"Не тяни себя за шею — поднимайся животом. Если ситапы очень тяжело или есть диастаз — «мёртвый жук», в два раза больше повторений","noteEn":"Do not pull on your neck — lift with the abdominals. If sit-ups are very hard or you have diastasis, do dead bugs instead — twice the reps"},{"exerciseId":"inchworm","unit":"reps","target":8,"restAfterSec":0,"note":"Ровный темп: в каждом круге — одинаковое число червячков","noteEn":"An even pace: the same number of inchworms in every round"}]},{"kind":"cooldown","blockType":"cooldown","format":"sets","sets":1,"setsField":"sets","title":"Заминка и растяжка","titleEn":"Cool-down and stretch","description":"Не пропускаем. Дыши медленно, тяни до приятного натяжения, не через боль. Потом потрать 2–3 минуты и отметь в приложении, как было: усилие, что далось легко, что оказалось тяжёлым, было ли что-то, что вызвало дискомфорт. Через несколько недель ты увидишь по этим записям, насколько легче стало тренироваться. А если в какой-то день потренироваться не получилось — не страшно, выйди на прогулку.","descriptionEn":"Do not skip it. Breathe slowly, stretch to a pleasant pull, never into pain. Then take 2–3 minutes and record in the app how it went: the effort, what felt easy, what turned out hard, anything that caused discomfort. In a few weeks these notes will show you how much easier training has become. And on a day you could not train at all — no drama, go for a walk.","scalable":false,"blockId":"cd_stretch","items":[{"exerciseId":"cat_cow","unit":"reps","target":6,"restAfterSec":0},{"exerciseId":"quad_stretch","unit":"seconds","target":30,"perSide":true,"restAfterSec":0},{"exerciseId":"hamstring_stretch","unit":"seconds","target":25,"perSide":true,"restAfterSec":0},{"exerciseId":"hip_flexor_stretch","unit":"seconds","target":20,"perSide":true,"restAfterSec":0},{"exerciseId":"child_pose","unit":"seconds","target":45,"restAfterSec":0}]}]}'::jsonb, 110)
on conflict (short_id) do update set
  title = excluded.title,
  description = excluded.description,
  structure = excluded.structure,
  points = excluded.points,
  updated_at = now();

insert into public.custom_workouts (short_id, title, description, structure, points)
values ('start_w_s18_intervals', 'Два интервала: верх и низ', 'Тренировка 18. Два интервала по 2 минуты. Первый: входной билет — отжимания, в оставшееся время — максимум червячков. Минута отдыха. Второй: входной билет — выпады, в оставшееся время — максимум ситапов. Отжимания тяжело — с колен.',
  '{"sections":[{"kind":"warmup","blockType":"warmup","format":"circuit","sets":1,"setsField":"sets","title":"Разминка: суставная гимнастика","titleEn":"Warm-up: joint mobility","description":"Обязательно перед каждой тренировкой. Идём сверху вниз: шея, плечи, локти и кисти, корпус, таз, колени, стопы. Спокойный темп, амплитуда растёт постепенно, без рывков. Разминка не входит в тренировку — это подготовка. Резкая боль — не норма: остановись.","descriptionEn":"Mandatory before every session. Top to bottom: neck, shoulders, elbows and wrists, trunk, hips, knees, ankles. Easy pace, the range grows gradually, no jerks. The warm-up is not part of the workout — it is preparation. Sharp pain is not normal: stop.","scalable":false,"blockId":"wu_mobility","items":[{"exerciseId":"neck_circles","unit":"seconds","target":20,"restAfterSec":0,"note":"Полукруги спереди, назад не запрокидываем","noteEn":"Half-circles across the front, no dropping back"},{"exerciseId":"arm_circles","unit":"seconds","target":20,"restAfterSec":0,"note":"Половину вперёд, половину назад","noteEn":"Half forward, half backward"},{"exerciseId":"elbow_wrist_circles","unit":"seconds","target":20,"restAfterSec":0},{"exerciseId":"side_bend","unit":"seconds","target":20,"restAfterSec":0},{"exerciseId":"hip_circles","unit":"seconds","target":20,"restAfterSec":0,"note":"В обе стороны","noteEn":"Both directions"},{"exerciseId":"leg_swing","unit":"reps","target":6,"perSide":true,"restAfterSec":0},{"exerciseId":"knee_circles","unit":"seconds","target":20,"restAfterSec":0,"note":"Круги маленькие, пятки на полу","noteEn":"Small circles, heels down"},{"exerciseId":"ankle_circles","unit":"seconds","target":15,"perSide":true,"restAfterSec":0},{"exerciseId":"squat_to_stand","unit":"reps","target":5,"restAfterSec":0,"note":"Медленно, до комфортной глубины","noteEn":"Slowly, to a comfortable depth"}]},{"kind":"main","blockType":"metcon","format":"fortime","sets":1,"setsField":"sets","durationSec":60,"title":"Интервал 1: отжимания","titleEn":"Interval 1: push-ups","description":"Входной билет — отжимания. Сделал — сразу к червячкам.","descriptionEn":"The buy-in is push-ups. Done — straight on to the inchworms.","scalable":true,"blockId":"s18_first","items":[{"exerciseId":"push_up","unit":"reps","target":15,"restAfterSec":0,"note":"Корпус ровно, локти назад под 45°, грудь к полу. Тяжело — с колен или от высокой опоры","noteEn":"Body straight, elbows back at 45 degrees, chest to the floor. Too hard? From the knees or a high surface"}]},{"kind":"main","blockType":"metcon","format":"amrap","sets":1,"setsField":"none","durationSec":60,"title":"Интервал 1: максимум червячков","titleEn":"Interval 1: max inchworms","description":"До конца интервала — максимум червячков. Потом минута отдыха.","descriptionEn":"Max inchworms until the interval is up. Then one minute of rest.","scalable":true,"blockId":"s18_first_max","items":[{"exerciseId":"inchworm","unit":"reps","target":8,"restAfterSec":0,"note":"Максимум за оставшееся время, спина ровная","noteEn":"As many as possible in the time left, back flat"}]},{"kind":"main","blockType":"metcon","format":"fortime","sets":1,"setsField":"sets","durationSec":60,"title":"Интервал 2: выпады","titleEn":"Interval 2: lunges","description":"После минуты отдыха — входной билет: выпады. Сделал — сразу к ситапам.","descriptionEn":"After a minute of rest, the buy-in: lunges. Done — straight on to the sit-ups.","scalable":true,"blockId":"s18_second","items":[{"exerciseId":"reverse_lunge","unit":"reps","target":20,"restAfterSec":0,"note":"Считаем в сумме на две ноги. Шаг назад, колено мягко к полу, корпус прямой","noteEn":"Counted as the total for both legs. Step back, knee softly to the floor, trunk upright"}]},{"kind":"main","blockType":"metcon","format":"amrap","sets":1,"setsField":"none","durationSec":60,"title":"Интервал 2: максимум ситапов","titleEn":"Interval 2: max sit-ups","description":"До конца интервала — максимум ситапов (или «жука», вдвое больше).","descriptionEn":"Max sit-ups until the interval is up (or dead bugs, twice the reps).","scalable":true,"blockId":"s18_second_max","items":[{"exerciseId":"sit_up","unit":"reps","target":10,"restAfterSec":0,"note":"Максимум за оставшееся время. При диастазе — «жук»","noteEn":"As many as possible in the time left. With diastasis, dead bugs"}]},{"kind":"cooldown","blockType":"cooldown","format":"sets","sets":1,"setsField":"sets","title":"Заминка и растяжка","titleEn":"Cool-down and stretch","description":"Не пропускаем. Дыши медленно, тяни до приятного натяжения, не через боль. Потом потрать 2–3 минуты и отметь в приложении, как было: усилие, что далось легко, что оказалось тяжёлым, было ли что-то, что вызвало дискомфорт. Через несколько недель ты увидишь по этим записям, насколько легче стало тренироваться. А если в какой-то день потренироваться не получилось — не страшно, выйди на прогулку.","descriptionEn":"Do not skip it. Breathe slowly, stretch to a pleasant pull, never into pain. Then take 2–3 minutes and record in the app how it went: the effort, what felt easy, what turned out hard, anything that caused discomfort. In a few weeks these notes will show you how much easier training has become. And on a day you could not train at all — no drama, go for a walk.","scalable":false,"blockId":"cd_stretch","items":[{"exerciseId":"cat_cow","unit":"reps","target":6,"restAfterSec":0},{"exerciseId":"quad_stretch","unit":"seconds","target":30,"perSide":true,"restAfterSec":0},{"exerciseId":"hamstring_stretch","unit":"seconds","target":25,"perSide":true,"restAfterSec":0},{"exerciseId":"hip_flexor_stretch","unit":"seconds","target":20,"perSide":true,"restAfterSec":0},{"exerciseId":"child_pose","unit":"seconds","target":45,"restAfterSec":0}]}]}'::jsonb, 100)
on conflict (short_id) do update set
  title = excluded.title,
  description = excluded.description,
  structure = excluded.structure,
  points = excluded.points,
  updated_at = now();

insert into public.custom_workouts (short_id, title, description, structure, points)
values ('start_w_s19_inchworm_ladder', 'Лесенка червячков: точка отсчёта', 'Тренировка 19. Точка отсчёта. Каждую минуту — на одного червячка больше: 1-я минута 1, 2-я 2, и так до 10-й. Делаешь, пока укладываешься в минуту; закрыть все десять не обязательно. Запиши, на какой минуте остановился — через месяц-два повторишь и сравнишь.',
  '{"sections":[{"kind":"warmup","blockType":"warmup","format":"circuit","sets":1,"setsField":"sets","title":"Разминка: суставная гимнастика","titleEn":"Warm-up: joint mobility","description":"Обязательно перед каждой тренировкой. Идём сверху вниз: шея, плечи, локти и кисти, корпус, таз, колени, стопы. Спокойный темп, амплитуда растёт постепенно, без рывков. Разминка не входит в тренировку — это подготовка. Резкая боль — не норма: остановись.","descriptionEn":"Mandatory before every session. Top to bottom: neck, shoulders, elbows and wrists, trunk, hips, knees, ankles. Easy pace, the range grows gradually, no jerks. The warm-up is not part of the workout — it is preparation. Sharp pain is not normal: stop.","scalable":false,"blockId":"wu_mobility","items":[{"exerciseId":"neck_circles","unit":"seconds","target":20,"restAfterSec":0,"note":"Полукруги спереди, назад не запрокидываем","noteEn":"Half-circles across the front, no dropping back"},{"exerciseId":"arm_circles","unit":"seconds","target":20,"restAfterSec":0,"note":"Половину вперёд, половину назад","noteEn":"Half forward, half backward"},{"exerciseId":"elbow_wrist_circles","unit":"seconds","target":20,"restAfterSec":0},{"exerciseId":"side_bend","unit":"seconds","target":20,"restAfterSec":0},{"exerciseId":"hip_circles","unit":"seconds","target":20,"restAfterSec":0,"note":"В обе стороны","noteEn":"Both directions"},{"exerciseId":"leg_swing","unit":"reps","target":6,"perSide":true,"restAfterSec":0},{"exerciseId":"knee_circles","unit":"seconds","target":20,"restAfterSec":0,"note":"Круги маленькие, пятки на полу","noteEn":"Small circles, heels down"},{"exerciseId":"ankle_circles","unit":"seconds","target":15,"perSide":true,"restAfterSec":0},{"exerciseId":"squat_to_stand","unit":"reps","target":5,"restAfterSec":0,"note":"Медленно, до комфортной глубины","noteEn":"Slowly, to a comfortable depth"}]},{"kind":"main","blockType":"metcon","format":"emom","sets":10,"setsField":"rounds","title":"Лесенка червячков","titleEn":"The inchworm ladder","description":"По минутам, каждую на один больше. Это ориентир, а не тест на разрыв: остановись, где перестанешь укладываться, и запиши минуту.","descriptionEn":"By the minute, one more each time. A reference, not a test to failure: stop where you stop fitting the minute and note it.","scalable":false,"blockId":"s19_main","items":[{"exerciseId":"inchworm","unit":"reps","target":1,"restAfterSec":0,"note":"Шагай руками спокойно, спина ровная, колени можно чуть согнуть","noteEn":"Walk the hands calmly, back flat, knees may bend a little"},{"exerciseId":"inchworm","unit":"reps","target":2,"restAfterSec":0,"note":"Шагай руками спокойно, спина ровная, колени можно чуть согнуть","noteEn":"Walk the hands calmly, back flat, knees may bend a little"},{"exerciseId":"inchworm","unit":"reps","target":3,"restAfterSec":0,"note":"Шагай руками спокойно, спина ровная, колени можно чуть согнуть","noteEn":"Walk the hands calmly, back flat, knees may bend a little"},{"exerciseId":"inchworm","unit":"reps","target":4,"restAfterSec":0,"note":"Шагай руками спокойно, спина ровная, колени можно чуть согнуть","noteEn":"Walk the hands calmly, back flat, knees may bend a little"},{"exerciseId":"inchworm","unit":"reps","target":5,"restAfterSec":0,"note":"Шагай руками спокойно, спина ровная, колени можно чуть согнуть","noteEn":"Walk the hands calmly, back flat, knees may bend a little"},{"exerciseId":"inchworm","unit":"reps","target":6,"restAfterSec":0,"note":"Шагай руками спокойно, спина ровная, колени можно чуть согнуть","noteEn":"Walk the hands calmly, back flat, knees may bend a little"},{"exerciseId":"inchworm","unit":"reps","target":7,"restAfterSec":0,"note":"Шагай руками спокойно, спина ровная, колени можно чуть согнуть","noteEn":"Walk the hands calmly, back flat, knees may bend a little"},{"exerciseId":"inchworm","unit":"reps","target":8,"restAfterSec":0,"note":"Шагай руками спокойно, спина ровная, колени можно чуть согнуть","noteEn":"Walk the hands calmly, back flat, knees may bend a little"},{"exerciseId":"inchworm","unit":"reps","target":9,"restAfterSec":0,"note":"Шагай руками спокойно, спина ровная, колени можно чуть согнуть","noteEn":"Walk the hands calmly, back flat, knees may bend a little"},{"exerciseId":"inchworm","unit":"reps","target":10,"restAfterSec":0,"note":"Шагай руками спокойно, спина ровная, колени можно чуть согнуть","noteEn":"Walk the hands calmly, back flat, knees may bend a little"}]},{"kind":"cooldown","blockType":"cooldown","format":"sets","sets":1,"setsField":"sets","title":"Заминка и растяжка","titleEn":"Cool-down and stretch","description":"Не пропускаем. Дыши медленно, тяни до приятного натяжения, не через боль. Потом потрать 2–3 минуты и отметь в приложении, как было: усилие, что далось легко, что оказалось тяжёлым, было ли что-то, что вызвало дискомфорт. Через несколько недель ты увидишь по этим записям, насколько легче стало тренироваться. А если в какой-то день потренироваться не получилось — не страшно, выйди на прогулку.","descriptionEn":"Do not skip it. Breathe slowly, stretch to a pleasant pull, never into pain. Then take 2–3 minutes and record in the app how it went: the effort, what felt easy, what turned out hard, anything that caused discomfort. In a few weeks these notes will show you how much easier training has become. And on a day you could not train at all — no drama, go for a walk.","scalable":false,"blockId":"cd_stretch","items":[{"exerciseId":"cat_cow","unit":"reps","target":6,"restAfterSec":0},{"exerciseId":"quad_stretch","unit":"seconds","target":30,"perSide":true,"restAfterSec":0},{"exerciseId":"hamstring_stretch","unit":"seconds","target":25,"perSide":true,"restAfterSec":0},{"exerciseId":"hip_flexor_stretch","unit":"seconds","target":20,"perSide":true,"restAfterSec":0},{"exerciseId":"child_pose","unit":"seconds","target":45,"restAfterSec":0}]}]}'::jsonb, 90)
on conflict (short_id) do update set
  title = excluded.title,
  description = excluded.description,
  structure = excluded.structure,
  points = excluded.points,
  updated_at = now();

insert into public.custom_workouts (short_id, title, description, structure, points)
values ('start_w_s20_finisher', 'Три круга: «жук», присед, отжимания', 'Тренировка 20. Финал курса: три круга — 20 «жуков», 10 приседаний, 10 отжиманий с колен. Спокойный темп, чистая техника. А теперь сравни ощущения после этой тренировки и после самой первой — почувствуй, насколько легче стало.',
  '{"sections":[{"kind":"warmup","blockType":"warmup","format":"circuit","sets":1,"setsField":"sets","title":"Разминка: суставная гимнастика","titleEn":"Warm-up: joint mobility","description":"Обязательно перед каждой тренировкой. Идём сверху вниз: шея, плечи, локти и кисти, корпус, таз, колени, стопы. Спокойный темп, амплитуда растёт постепенно, без рывков. Разминка не входит в тренировку — это подготовка. Резкая боль — не норма: остановись.","descriptionEn":"Mandatory before every session. Top to bottom: neck, shoulders, elbows and wrists, trunk, hips, knees, ankles. Easy pace, the range grows gradually, no jerks. The warm-up is not part of the workout — it is preparation. Sharp pain is not normal: stop.","scalable":false,"blockId":"wu_mobility","items":[{"exerciseId":"neck_circles","unit":"seconds","target":20,"restAfterSec":0,"note":"Полукруги спереди, назад не запрокидываем","noteEn":"Half-circles across the front, no dropping back"},{"exerciseId":"arm_circles","unit":"seconds","target":20,"restAfterSec":0,"note":"Половину вперёд, половину назад","noteEn":"Half forward, half backward"},{"exerciseId":"elbow_wrist_circles","unit":"seconds","target":20,"restAfterSec":0},{"exerciseId":"side_bend","unit":"seconds","target":20,"restAfterSec":0},{"exerciseId":"hip_circles","unit":"seconds","target":20,"restAfterSec":0,"note":"В обе стороны","noteEn":"Both directions"},{"exerciseId":"leg_swing","unit":"reps","target":6,"perSide":true,"restAfterSec":0},{"exerciseId":"knee_circles","unit":"seconds","target":20,"restAfterSec":0,"note":"Круги маленькие, пятки на полу","noteEn":"Small circles, heels down"},{"exerciseId":"ankle_circles","unit":"seconds","target":15,"perSide":true,"restAfterSec":0},{"exerciseId":"squat_to_stand","unit":"reps","target":5,"restAfterSec":0,"note":"Медленно, до комфортной глубины","noteEn":"Slowly, to a comfortable depth"}]},{"kind":"main","blockType":"metcon","format":"fortime","sets":3,"setsField":"sets","durationSec":600,"title":"Финальные круги","titleEn":"The final rounds","description":"Три круга в спокойном темпе. «Жук» медленно, поясница прижата; приседания и отжимания — чисто.","descriptionEn":"Three rounds at an easy pace. Dead bugs slow, lower back pressed down; squats and push-ups clean.","scalable":false,"blockId":"s20_main","items":[{"exerciseId":"dead_bug","unit":"reps","target":20,"restAfterSec":0,"note":"Поясница прижата к полу, движения медленные, корпус под контролем","noteEn":"Lower back pressed into the floor, slow movements, trunk under control"},{"exerciseId":"air_squat","unit":"reps","target":10,"restAfterSec":0,"note":"Пятки на полу, колени в стороны, глубина комфортная — не садись ниже, чем держится техника","noteEn":"Heels down, knees out, comfortable depth — no lower than your technique holds"},{"exerciseId":"knee_push_up","unit":"reps","target":10,"restAfterSec":0,"note":"Корпус ровно, живот напряжён, таз не проваливаем, локти не разводим широко. Тяжело — от высокой опоры","noteEn":"Body straight, belly braced, hips do not sag, elbows not flared. Too hard? Push up from a high surface"}]},{"kind":"cooldown","blockType":"cooldown","format":"sets","sets":1,"setsField":"sets","title":"Заминка и растяжка","titleEn":"Cool-down and stretch","description":"Не пропускаем. Дыши медленно, тяни до приятного натяжения, не через боль. Потом потрать 2–3 минуты и отметь в приложении, как было: усилие, что далось легко, что оказалось тяжёлым, было ли что-то, что вызвало дискомфорт. Через несколько недель ты увидишь по этим записям, насколько легче стало тренироваться. А если в какой-то день потренироваться не получилось — не страшно, выйди на прогулку.","descriptionEn":"Do not skip it. Breathe slowly, stretch to a pleasant pull, never into pain. Then take 2–3 minutes and record in the app how it went: the effort, what felt easy, what turned out hard, anything that caused discomfort. In a few weeks these notes will show you how much easier training has become. And on a day you could not train at all — no drama, go for a walk.","scalable":false,"blockId":"cd_stretch","items":[{"exerciseId":"cat_cow","unit":"reps","target":6,"restAfterSec":0},{"exerciseId":"quad_stretch","unit":"seconds","target":30,"perSide":true,"restAfterSec":0},{"exerciseId":"hamstring_stretch","unit":"seconds","target":25,"perSide":true,"restAfterSec":0},{"exerciseId":"hip_flexor_stretch","unit":"seconds","target":20,"perSide":true,"restAfterSec":0},{"exerciseId":"child_pose","unit":"seconds","target":45,"restAfterSec":0}]}]}'::jsonb, 100)
on conflict (short_id) do update set
  title = excluded.title,
  description = excluded.description,
  structure = excluded.structure,
  points = excluded.points,
  updated_at = now();

